INSERT INTO companies (id, name, logo, description, province, location) VALUES
    (1, 'บริษัท ซีดีจี กรุ๊ป จำกัด', 'C01.jpg', 'ผู้ให้บริการระบบเทคโนโลยีสารสนเทศ (IT Solutions) และ System Integration ครบวงจร', 'กรุงเทพมหานคร', '202 ถนนนางลิ้นจี่ แขวงช่องนนทรี เขตยานนาวา กรุงเทพมหานคร 10120'),
    (2, 'ศูนย์เทคโนโลยีอิเล็กทรอนิกส์และคอมพิวเตอร์แห่งชาติ (NECTEC)', 'C02.png', 'หน่วยงานวิจัยและพัฒนาด้านเทคโนโลยีอิเล็กทรอนิกส์และคอมพิวเตอร์ของรัฐ', 'ปทุมธานี', 'ศูนย์เทคโนโลยีอิเล็กทรอนิกส์และคอมพิวเตอร์แห่งชาติ (NECTEC) 112 ถนนพหลโยธิน'),
    (3, 'ตลาดหลักทรัพย์แห่งประเทศไทย (SET)', 'C03.jpg', 'ศูนย์กลางการซื้อขายหลักทรัพย์และให้บริการที่เกี่ยวเนื่องกับตลาดทุนของประเทศไทย', 'กรุงเทพมหานคร', 'เลขที่ 93 ถนนรัชดาภิเษก แขวงดินแดง เขตดินแดง กรุงเทพฯ 10400'),
    (4, 'ธนาคารกรุงเทพ จำกัด (มหาชน)', 'C04.jpg', 'สถาบันการเงินและธนาคารพาณิชย์ชั้นนำของประเทศไทย ให้บริการทางการเงินครบวงจร', 'กรุงเทพมหานคร', '333 ถนนสีลม แขวงสีลม เขตบางรัก กรุงเทพมหานคร 10500'),
    (5, 'ธนาคารทหารไทยธนชาต จำกัด (มหาชน)', 'C05.webp', 'สถาบันการเงินและธนาคารพาณิชย์ที่มุ่งเน้นการให้บริการทางการเงินและสร้างชีวิตทางการเงินที่ดีขึ้น', 'กรุงเทพมหานคร', 'ทีทีบี สำนักงานใหญ่ 3000 ถนนพหลโยธิน แขวงจอมพล เขตจตุจักร กรุงเทพมหานคร 10900'),
    (6, 'ธนาคารไทยพาณิชย์ จำกัด (มหาชน)', 'C06.jpg', 'สถาบันการเงินชั้นนำของไทย ผู้นำด้านนวัตกรรมดิจิทัลแบงก์กิ้งและบริการทางการเงิน', 'กรุงเทพมหานคร', 'ธนาคารไทยพาณิชย์ จำกัด (มหาชน) สำนักงานใหญ่ 9 ถ.รัชดาภิเษก แขวงจตุจักร เขตจตุจักร กรุงเทพฯ 10900'),
    (7, 'บริษัท เงินเทอร์โบ จำกัด (มหาชน)', 'C09.png', 'ผู้ให้บริการสินเชื่อรายย่อย สินเชื่อทะเบียนรถ และสินเชื่อโฉนดที่ดินที่เข้าถึงง่าย', 'นนทบุรี', '500 หมู่ 3 ถนนติวานนท์ ตำบลบ้านใหม่ อำเภอปากเกร็ด จังหวัดนนทบุรี 11120'),
    (8, 'บริษัท จีเอเบิล จำกัด (มหาชน)', 'C10.png', 'ผู้ให้บริการด้านดิจิทัลโซลูชันและระบบเทคโนโลยีสารสนเทศแบบครบวงจรชั้นนำของไทย', 'กรุงเทพมหานคร', '127/30 อาคารปัญจธานี ชั้น 25 ถนนนนทรี แขวงช่องนนทรี เขตยานนาวา กรุงเทพมหานคร 10120'),
    (9, 'บริษัท เจริญโภคภัณฑ์อาหาร จำกัด (มหาชน)', 'C11.png', 'ผู้นำด้านอุตสาหกรรมเกษตรและอาหารครบวงจรระดับโลก (อาหารสัตว์ ฟาร์ม และอาหาร)', 'กรุงเทพมหานคร', '313 อาคารซี.พี. ทาวเวอร์ ถนนสีลม แขวงสีลม เขตบางรัก กรุงเทพมหานคร 10500'),
    (10, 'บริษัท ซี.เจ. เอ็กซ์เพรส กรุ๊ป จำกัด', 'C12.png', 'ผู้ดำเนินธุรกิจค้าปลีก ซูเปอร์มาร์เก็ต และร้านสะดวกซื้อรูปแบบใหม่ภายใต้แบรนด์ CJ', 'กรุงเทพมหานคร', '393 อาคาร 393 สีลม ชั้น 2, 4 และ 5 ถนนสีลม แขวงสีลม เขตบางรัก กรุงเทพมหานคร 10500'),
    (11, 'บริษัท ที.ซี.ซี. เทคโนโลยี จำกัด', 'C13.webp', 'ผู้ให้บริการโครงสร้างพื้นฐานด้านไอที ศูนย์ข้อมูล (Data Center) และคลาวด์โซลูชัน', 'กรุงเทพมหานคร', '2 ห้องเลขที่ 1501-1504 ชั้น 15 อาคารสีลมเอจ ถนนสีลม แขวงสุริยวงศ์ เขตบางรัก กรุงเทพมหานคร 10500'),
    (12, 'บริษัท ไทยประกันชีวิต จำกัด (มหาชน)', 'C14.svg', 'บริษัทประกันชีวิตชั้นนำของคนไทย ให้บริการวางแผนการเงินและประกันสุขภาพ', 'กรุงเทพมหานคร', '123 อาคารไทยประกันชีวิต 1 ถนนรัชดาภิเษก แขวงดินแดง เขตดินแดง กรุงเทพมหานคร 10400'),
    (13, 'บริษัท บีอีซี เวิลด์ จำกัด (มหาชน)', 'C16.svg', 'ผู้ดำเนินธุรกิจสื่อ โทรทัศน์ (ช่อง 3) ผลิตรายการและคอนเทนต์ความบันเทิงชั้นนำ', 'กรุงเทพมหานคร', '3199 อาคาร มาลีนนท์ ทาวเวอร์ ชั้น 2, 3, 4, 7, 9, 10, 30-34 ถนน พระราม 4 แขวงคลองตัน เขตคลองเตย กรุงเทพมหานคร 10110'),
    (14, 'บริษัท เบทาโกร จำกัด (มหาชน)', 'C17.png', 'ผู้ประกอบธุรกิจอุตสาหกรรมเกษตรและอาหารครบวงจรชั้นนำของไทย', 'กรุงเทพมหานคร', '323 หมู่ที่ 6 แขวงทุ่งสองห้อง เขตหลักสี่ กรุงเทพมหานคร 10210'),
    (15, 'บริษัท ปูนซิเมนต์ไทย จำกัด (มหาชน)', 'C18.jpg', 'กลุ่มบริษัทชั้นนำด้านธุรกิจซีเมนต์ วัสดุก่อสร้าง เคมีภัณฑ์ และแพ็กเกจจิ้ง (SCG)', 'กรุงเทพมหานคร', '1 ถนนปูนซิเมนต์ไทย แขวงบางซื่อ เขตบางซื่อ กรุงเทพมหานคร 10800'),
    (16, 'บริษัท อยุธยา แคปปิตอล ออโต้ ลีส จำกัด (มหาชน)', 'C24.jpg', 'ผู้ให้บริการสินเชื่อยานยนต์ครบวงจรชั้นนำของไทย (กรุงศรี ออโต้)', 'ปทุมธานี', '131 อาคารกลุ่มนวัตกรรม 1 ชั้นที่ 2 ห้องเลขที่ ไอเอ็นซี 1-201 หมู่ที่ 9 ตำบลคลองหนึ่ง อำเภอคลองหลวง จ.ปทุมธานี'),
    (17, 'บริษัท อะไรส์ บาย อิน ฟินิธัส จำกัด', 'C25.jpg', 'บริษัทเทคโนโลยีในเครือธนาคารกรุงไทย มุ่งพัฒนานวัตกรรมและแพลตฟอร์มดิจิทัลระดับประเทศ', 'กรุงเทพมหานคร', '88 อาคารเดอะ ปาร์ค ชั้น 5, 9-10 ถนนรัชดาภิเษก แขวงคลองเตย เขตคลองเตย กรุงเทพมหานคร 10110'),
    (18, 'บริษัท เอ็ม 365 (ประเทศไทย) จำกัด', 'C26.png', 'ผู้ให้บริการคำปรึกษา พัฒนาระบบไอที (IT Consulting) และโซลูชันด้านคลาวด์องค์กร', 'กรุงเทพมหานคร', '287 อาคารลิเบอร์ตี้ สแควร์ ห้องเลขที่ 1804 ชั้นที่ 18 ถนนสีลม แขวงสีลม เขตบางรัก กรุงเทพมหานคร 10500'),
    (19, 'บริษัท ไอทีวัน จำกัด', 'C27.jfif', 'ผู้ให้บริการให้คำปรึกษา พัฒนา และบริหารจัดการระบบเทคโนโลยีสารสนเทศ (บริษัทร่วมทุนระหว่าง SCG และ Accenture)', 'กรุงเทพมหานคร', '118/1 อาคารทิปโก้ ชั้น 21-22 ถนนพระราม 6 แขวงพญาไท เขตพญาไท กรุงเทพมหานคร 10400'),
    (20, 'บริษัท ไอบอทน้อย จำกัด', 'C28.webp', 'บริษัทผู้พัฒนาเทคโนโลยี AI, Data Science และระบบแชทบอทอัจฉริยะภาษาไทย', 'กรุงเทพมหานคร', '30 หมู่บ้านเศรษฐสิริ ราชพฤกษ์ จรัญฯ ซอยปากน้ำฝั่งเหนือ 11 แขวงคลองชักพระ เขตตลิ่งชัน กรุงเทพมหานคร 10170'),
    (21, 'บริษัทกสิกร บิซิเนส-เทคโนโลยี กรุ๊ป', 'C29.jfif', 'บริษัทผู้นำด้านเทคโนโลยีและนวัตกรรมดิจิทัล (KBTG) ในเครือธนาคารกสิกรไทย', 'นนทบุรี', '46/6 ถนนป๊อบปูล่า ตำบลบ้านใหม่ อำเภอปากเกร็ด จ.นนทบุรี 11120'),
    (22, 'บริษัทหลักทรัพย์ หยวนต้า (ประเทศไทย) จำกัด', 'C30.webp', 'บริษัทหลักทรัพย์ชั้นนำ ให้บริการนายหน้าซื้อขายหลักทรัพย์และการลงทุนด้านการเงิน', 'กรุงเทพมหานคร', '127 อาคารเกษร ทาวเวอร์ ชั้น 14-16 ถนนราชดำริ'),
    (23, 'สำนักงานพัฒนาธุรกรรมทางอิเล็กทรอนิกส์ (สพธอ.)', 'C31.jpeg', 'หน่วยงานรัฐที่มีบทบาทส่งเสริม พัฒนา และกำกับดูแลการทำธุรกรรมทางอิเล็กทรอนิกส์ (ETDA)', 'กรุงเทพมหานคร', 'ศูนย์ราชการเฉลิมพระเกียรติ 80 พรรษา (อาคารบี) ชั้นที่ 6 เลขที่ 120 หมู่ที่ 3 ถนนแจ้งวัฒนะ'),
    (24, 'บริษัท โกซอฟท์ (ประเทศไทย) จํากัด', 'C32.jpeg', 'ผู้ให้บริการและพัฒนาระบบเทคโนโลยีสารสนเทศ ฐานข้อมูล และแอปพลิเคชัน ในกลุ่มธุรกิจ CP ALL', 'นนทบุรี', 'อาคาร THE TARA เลขที่ 58/28 หมู่ 2 ถนนแจ้งวัฒนะ ตำบลบางตลาด อำเภอปากเกร็ด จังหวัดนนทบุรี 11120'),
    (25, 'บริษัท เอสซีบี เทคเอกซ์ จำกัด', 'C33.jpeg', 'บริษัทผู้เชี่ยวชาญด้านเทคโนโลยีและพัฒนานวัตกรรมดิจิทัลเพื่อธุรกิจในเครือ SCBX', 'กรุงเทพมหานคร', '19 อาคารไทยพาณิชย์ ปาร์ค พลาซ่า เวสท์ บี ชั้นที่ 21 ถนนรัชดาภิเษก แขวงจตุจักร เขตจตุจักร กรุงเทพมหานคร 10900'),
    (26, 'บริษัท พีทีที ดิจิตอล โซลูชั่น จำกัด', 'C34.png', 'ผู้ให้บริการและพัฒนาระบบเทคโนโลยีสารสนเทศ (IT Solutions) สำหรับกลุ่ม ปตท.', 'ระยอง', 'เลขที่ 59 ถนนราษฎร์นิยม ตำบลเนินพระ อำเภอเมืองระยอง จังหวัดระยอง 21150'),
    (27, 'บริษัท อินฟิไลท์ จำกัด', NULL, 'ผู้ให้บริการพัฒนาซอฟต์แวร์ เว็บไซต์ และแอปพลิเคชัน (Software Development)', 'นนทบุรี', '99/207 หมู่บ้าน นนทรี รีเจ้นท์ หมู่ที่ 4 ถนนราชพฤกษ์ ตำบลบางขนุน อำเภอบางกรวย จ.นนทบุรี'),
    (28, 'บริษัท ไลน์แมน วงใน จำกัด', 'C36.jfif', 'แพลตฟอร์มไลฟ์สไตล์และบริการจัดส่งอาหาร (Food Delivery) ครบวงจรชั้นนำของไทย', 'กรุงเทพมหานคร', '195 อาคารวัน แบงค็อก ทาวเวอร์ 4 ชั้นที่ 24 ห้องเลขที่ 2411-2412 และชั้นที่ 25 ห้องเลขที่ 2501-2514 ถนนวิทยุ แขวงลุมพินี เขตปทุมวัน กรุงเทพมหานคร 10330'),
    (29, 'บริษัท เอไอไนน์ จำกัด', 'C37.png', 'ผู้พัฒนาโซลูชันด้านปัญญาประดิษฐ์ (AI) สำหรับการวิเคราะห์ข้อมูลและประมวลผลภาษาไทย', 'ปทุมธานี', '131 อาคารกลุ่มนวัตกรรม 1 ชั้นที่ 2 ห้องเลขที่ ไอเอ็นซี 1-201 หมู่ที่ 9 ตำบลคลองหนึ่ง อำเภอคลองหลวง จ.ปทุมธานี'),
    (30, 'บริษัทเอสซีจี เคมิคอลส์ จํากัด (มหาชน)', 'C38.jpg', 'ผู้ประกอบธุรกิจเคมีภัณฑ์แบบครบวงจรระดับภูมิภาคในเครือ SCG', 'กรุงเทพมหานคร', '1 ถนนปูนซิเมนต์ไทย บางซื่อ กรุงเทพฯ 10800'),
    (31, 'บริษัท สยามคูโบต้าคอร์ปอเรชั่น จำกัด', 'C39.png', 'ผู้นำด้านนวัตกรรมเครื่องจักรกลการเกษตรและเทคโนโลยีการเกษตรแบบครบวงจร', 'ปทุมธานี', 'สำนักงานใหญ่ 101/19-24 หมู่ที่ 20 นิคมอุตสาหกรรมนวนคร ต.คลองหนึ่ง อ.คลองหลวง จ.ปทุมธานี 12120'),
    (32, 'บริษัท ทิสโก้ อินฟอร์เมชั่นเทคโนโลยี จำกัด', 'C40.png', 'ผู้ให้บริการและพัฒนาระบบเทคโนโลยีสารสนเทศเพื่อสนับสนุนธุรกิจในเครือกลุ่มทิสโก้', 'กรุงเทพมหานคร', '48/12 อาคารทิสโก้ทาวเวอร์ ชั้น 6 ถนนสาทรเหนือ แขวงสีลม เขตบางรัก กรุงเทพมหานคร 10500'),
    (33, 'กองออกแบบและพัฒนาผลิตภัณฑ์ดิจิทัล สำนักดิจิทัล การไฟฟ้าส่วนภูมิภาค', 'C41.png', 'หน่วยงานพัฒนาผลิตภัณฑ์ดิจิทัลและนวัตกรรมเพื่อสนับสนุนการให้บริการของการไฟฟ้าส่วนภูมิภาค (PEA)', 'กรุงเทพมหานคร', '121/1-2 ถนนเพชรบุรี แขวงทุ่งพญาไท เขตราชเทวี กรุงเทพฯ 10400'),
    (35, 'บริษัท อโกดา เซอร์วิสเซส จำกัด', 'C43.png', 'แพลตฟอร์มผู้ให้บริการจองที่พักและบริการด้านการท่องเที่ยวออนไลน์ระดับโลก', 'กรุงเทพมหานคร', '999/9 อาคารดิออฟฟิศเศส แอท เซ็นทรัลเวิลด์ ชั้น 6-9, 11-12, 16, 22, 27, 36 และ44 ถนนพระราม 1 แขวงปทุมวัน เขตปทุมวัน กรุงเทพมหานคร 10330'),
    (36, 'กลุ่มบริษัทแอดวานซ์ อินโฟร์ เซอร์วิส จำกัด (มหาชน)', 'C44.jpg', 'ผู้ให้บริการเครือข่ายโทรคมนาคม อินเทอร์เน็ต และบริการดิจิทัลอันดับหนึ่งของไทย (AIS)', 'กรุงเทพมหานคร', 'เลขที่ 414 อาคาร เอไอเอส 1 ถนนพหลโยธิน แขวงสามเสนใน เขตพญาไท กรุงเทพฯ 10400'),
    (37, 'บริษัท บางจาก คอร์ปอเรชั่น จำกัด (มหาชน)', 'C45.jpg', 'ผู้นำด้านธุรกิจพลังงาน โรงกลั่นน้ำมัน และพลังงานทดแทนชั้นนำของไทย', 'กรุงเทพมหานคร', '2098 อาคารเอ็ม ทาวเวอร์ ชั้นที่ 8 ถนนสุขุมวิท แขวงพระโขนงใต้ เขตพระโขนง กรุงเทพมหานคร 10260'),
    (38, 'บริษัท เบลนเดต้า จำกัด', 'C46.jfif', 'บริษัทผู้พัฒนาแพลตฟอร์มบริหารจัดการและวิเคราะห์ข้อมูลขนาดใหญ่ (Big Data Analytics) สำหรับองค์กร', 'กรุงเทพมหานคร', '110/1 ถนนกรุงธนบุรี แขวงบางลำภูล่าง เขตคลองสาน กรุงเทพมหานคร 10600'),
    (39, 'บริษัท เซ็นทรัล รีเทล คอร์ปอเรชั่น จำกัด (มหาชน)', 'C47.jfif', 'ผู้นำธุรกิจค้าปลีกแบบ Omni-channel หลากหลายหมวดหมู่ในเครือเซ็นทรัลกรุ๊ป', 'กรุงเทพมหานคร', '22 ซอยสมคิด ถนนเพลินจิต แขวงลุมพินี เขตปทุมวัน กรุงเทพมหานคร 10330'),
    (40, 'บริษัท คลาวด์ เอชเอ็ม จำกัด', 'C48.png', 'ผู้ให้บริการคลาวด์ (Cloud Services) ครบวงจรสำหรับองค์กรระดับ Enterprise ในไทย', 'กรุงเทพมหานคร', '499 ถนนกำแพงเพชร 6 แขวงลาดยาว เขตจตุจักร กรุงเทพมหานคร 10900'),
    (41, 'บริษัท เดลิเทค จำกัด', 'C49.png', 'ผู้เชี่ยวชาญด้านระบบ Cloud Solutions และผู้ให้บริการคำปรึกษาด้านเทคโนโลยี (AWS Partner)', 'กรุงเทพมหานคร', '171 ซอยพระรามที่ 3 ซ.77 แขวงช่องนนทรี เขตยานนาวา กรุงเทพมหานคร 10120'),
    (42, 'บริษัท เอ็กซอนโมบิล จำกัด', 'C50.png', 'บริษัทพลังงานชั้นนำระดับโลก ประกอบธุรกิจสำรวจ ผลิตน้ำมัน ปิโตรเคมี และพลังงาน', 'กรุงเทพมหานคร', '3195/17-29 ถนนพระราม 4 แขวงคลองตัน เขตคลองเตย กรุงเทพมหานคร 10110'),
    (43, 'บริษัท หัวเว่ย เทคโนโลยี่ (ประเทศไทย) จำกัด', 'C51.jfif', 'ผู้ให้บริการโซลูชันไอซีที สมาร์ทดีไวซ์ และโครงสร้างพื้นฐานด้านโทรคมนาคมระดับโลก', 'กรุงเทพมหานคร', '9 อาคารจี ทาวเวอร์ แกรนด์ พระราม 9 ห้องเลขที่ จีเอ็น 01-04 ชั้น 34-39 ถนนพระราม 9 แขวงห้วยขวาง เขตห้วยขวาง กรุงเทพมหานคร 10310'),
    (44, 'บริษัท อินโนเวทีฟ เอ็กซ์ตรีมิสต์ จำกัด', 'C52.png', 'ผู้ให้บริการให้คำปรึกษา ออกแบบ และพัฒนาระบบซอฟต์แวร์ระดับองค์กร', 'กรุงเทพมหานคร', '3 อาคารพร้อมพันธุ์ 3 ชั้นที่ 16 ห้องเลขที่ 1608-1614 ซอยลาดพร้าว 3 ถนนลาดพร้าว แขวงจอมพล เขตจตุจักร กรุงเทพมหานคร 10900'),
    (45, 'บริษัท คิง เพาเวอร์ คลิก จำกัด', 'C53.jpg', 'บริษัทผู้พัฒนาแพลตฟอร์มอีคอมเมิร์ซและโซลูชันดิจิทัล เพื่อสนับสนุนธุรกิจในเครือ King Power', 'กรุงเทพมหานคร', '8 ถนนรางน้ำ แขวงถนนพญาไท เขตราชเทวี กรุงเทพมหานคร 10400'),
    (46, 'ตลาดหลักทรัพย์ลอนดอน (LSEG)', 'C54.png', 'ศูนย์กลางให้บริการข้อมูลทางการเงินระดับโลกและการวิเคราะห์ตลาดการเงิน (London Stock Exchange Group)', 'กรุงเทพมหานคร', '968 U Chu Liang Building, 34th Floor, Silom, Bang Rak, Bangkok 10500, Thailand'),
    (47, 'บริษัท กรุ๊ป-ไอบี เอสอีเอ จำกัด', NULL, 'บริษัทผู้เชี่ยวชาญระดับโลกด้านความมั่นคงปลอดภัยทางไซเบอร์ (Cybersecurity) และป้องกันภัยคุกคามทางดิจิทัล', 'ภูเก็ต', '77/77 หมู่ที่ 5 ตำบลรัษฎา อำเภอเมืองภูเก็ต จ.ภูเก็ต 83000'),
    (48, 'บริษัท ไทยสมุทรประกันชีวิต จำกัด (มหาชน)', 'C56.jpg', 'บริษัทประกันชีวิตชั้นนำที่ให้บริการด้านการคุ้มครองสุขภาพและการวางแผนทางการเงิน', 'กรุงเทพมหานคร', '170/74-83 อาคารโอเชี่ยนทาวเวอร์ 1 ถนนรัชดาภิเษก แขวงคลองเตย เขตคลองเตย กรุงเทพมหานคร 10110'),
    (49, 'บริษัท ไอเดียแล็บ จำกัด', 'c57.png', 'บริษัทผู้เชี่ยวชาญด้านการพัฒนาซอฟต์แวร์ แอปพลิเคชัน และสร้างสรรค์นวัตกรรมดิจิทัลสำหรับธุรกิจ', 'กรุงเทพมหานคร', '999/9 อาคารดิ ออฟฟิศเศส แอท เซ็นทรัลเวิลด์ ชั้น 16 ห้อง OFML1605-6 ถนนพระราม1 แขวงปทุมวัน เขตปทุมวัน กรุงเทพมหานคร 10330'),
    (50, 'บริษัท บี ทรี เทคโนโลยี จำกัด', 'c58.jpeg', 'ผู้ให้บริการด้าน IT Solutions การพัฒนาระบบซอฟต์แวร์ และที่ปรึกษาด้านดิจิทัลองค์กร', 'กรุงเทพมหานคร', '1/7 ซอยลาดพร้าว 64 แยก 4 แขวงวังทองหลาง เขตวังทองหลาง กรุงเทพมหานคร 10310'),
    (51, 'ธนาคารเกียรตินาคินภัทร จำกัด (มหาชน)', 'c59.jpeg', 'สถาบันการเงินที่ให้บริการทั้งด้านธนาคารพาณิชย์และธุรกิจตลาดทุนแบบครบวงจร', 'กรุงเทพมหานคร', '209 อาคารเคเคพี ทาวเวอร์ ถนนสุขุมวิท 21 (อโศก) แขวงคลองเตยเหนือ เขตวัฒนา กรุงเทพมหานคร 10110'),
    (52, 'บริษัทดูโฮม จำกัด (มหาชน)', 'c60.svg', 'ผู้ดำเนินธุรกิจค้าปลีกและค้าส่งวัสดุก่อสร้าง อุปกรณ์ตกแต่งบ้าน และสินค้าเครื่องใช้ในบ้านครบวงจร', 'ปทุมธานี', '88/111 ต.บางพูน อ.เมือง จ.ปทุมธานี'),
    (53, 'บริษัท สกิลเลน เทคโนโลยี จำกัด (มหาชน)', 'c61.jpg', 'ผู้ให้บริการแพลตฟอร์มการเรียนรู้ออนไลน์ (EdTech) และพัฒนาทักษะสำหรับบุคคลและองค์กร (SkillLane)', 'กรุงเทพมหานคร', '1 อาคารเอ็มไพร์ ทาวเวอร์ ชั้นที่ 35 ห้องเลขที่ 3510,3511 ถนนสาทรใต้ แขวงยานนาวา เขตสาทร กรุงเทพมหานคร 10120'),
    (54, 'บริษัท เก็ต ออน เทคโนโลยี จำกัด', 'c62.jpeg', 'ผู้จัดจำหน่ายและให้บริการโซลูชันระบบโครงสร้างพื้นฐานด้านไอที (Enterprise IT Infrastructure)', 'กรุงเทพมหานคร', '9/196 ซอยรัชประชา 4 ถนนรัชดาภิเษก แขวงจตุจักร เขตจตุจักร กรุงเทพมหานคร 10900'),
    (55, 'บริษัท ดาต้าฟาร์ม จำกัด', 'c63.jpeg', 'ผู้เชี่ยวชาญด้าน Cyber Security ให้บริการทดสอบเจาะระบบ (Penetration Testing) และตรวจสอบความปลอดภัยทางไอที', 'กรุงเทพมหานคร', '3 อาคารซี.พี.ทาวเวอร์ 2 (ฟอร์จูนทาวน์) ชั้น 21 ถนนรัชดาภิเษก แขวงดินแดง เขตดินแดง กรุงเทพมหานคร 10400'),
    (56, 'บริษัท เอ็ดไวซอรี่ จำกัด (สำนักงานใหญ่)', 'c64.png', 'ผู้พัฒนาแพลตฟอร์มด้านการศึกษา (EdTech) และระบบวิเคราะห์ประเมินทักษะสำหรับองค์กร', 'กรุงเทพมหานคร', '111 ทรูดิจิทัล พาร์ค เวสต์ อาคารยูนิคอร์น ชั้น 5 ห้อง SH561 และ SH564 ถนนสุขุมวิท แขวงบางจาก เขตพระโขนง กรุงเทพมหานคร 10260'),
    (57, 'บริษัท กรุงศรี นิมเบิล จำกัด', 'c65.png', 'บริษัทศูนย์กลางด้านเทคโนโลยีและพัฒนานวัตกรรมดิจิทัลในเครือธนาคารกรุงศรีอยุธยา', 'กรุงเทพมหานคร', '1222 อาคารธนาคารกรุงศรีอยุธยา จำกัด (มหาชน) สำนักงานใหญ่ ชั้นที่ 21 ถนนพระรามที่ 3 แขวงบางโพงพาง เขตยานนาวา กรุงเทพมหานคร 10120'),
    (58, 'โรงพยาบาลสินแพทย์ลำลูกกา', 'c66.jpeg', 'สถานพยาบาลและโรงพยาบาลเอกชนชั้นนำที่ให้บริการด้านการแพทย์และดูแลสุขภาพแบบครบวงจร', 'ปทุมธานี', '37/29 หมู่ที่ 3 ตำบลคูคต อำเภอลำลูกกา จ.ปทุมธานี 12130'),
    (59, 'บริษัท ไอ.แอล.เอส จำกัด', 'c67.jpeg', 'ผู้ให้บริการโซลูชันระบบเทคโนโลยีสารสนเทศและการพัฒนาระบบสนับสนุนการปฏิบัติงานขององค์กร', 'นนทบุรี', 'เลขที่ 71 หมู่ 3 ถนนตัดใหม่ ต. บ้านใหม่ ปากเกร็ด นนทบุรี ประเทศไทย 11120'),
    (60, 'บริษัท ศุภาลัย จำกัด (มหาชน)', 'c68.png', 'ผู้พัฒนาธุรกิจอสังหาริมทรัพย์และที่อยู่อาศัย (บ้านและคอนโดมิเนียม) ชั้นนำของประเทศไทย', 'กรุงเทพมหานคร', '1011 ถนนพระราม 3 แขวงช่องนนทรี เขตยานนาวา กรุงเทพมหานคร 10120'),
    (61, 'บริษัท หัวเว่ย เทคโนโลยี่ (ประเทศไทย) จำกัด', 'c69.jpeg', 'ผู้ให้บริการโซลูชันไอซีที สมาร์ทดีไวซ์ และโครงสร้างพื้นฐานด้านโทรคมนาคมระดับโลก', 'กรุงเทพมหานคร', '9 อาคารจี ทาวเวอร์ แกรนด์ พระราม 9 ห้องเลขที่ จีเอ็น 01-04 ชั้น 34-39 ถนนพระราม 9 แขวงห้วยขวาง เขตห้วยขวาง กรุงเทพมหานคร 10310'),
    (62, 'บริษัท คิวบ์ ซอฟท์เทค จำกัด', 'c70.jpeg', 'บริษัทผู้พัฒนาซอฟต์แวร์ เว็บไซต์ โมบายแอปพลิเคชัน และให้บริการด้าน IT Outsource สำหรับองค์กร', 'กรุงเทพมหานคร', '160/170-2 อาคารไอทีเอฟ-สีลมพาเลส ชั้น 13 ถนนสีลม แขวงสุริยวงศ์ เขตบางรัก กรุงเทพมหานคร 10500'),
    (63, 'บริษัท ซีพี ออลล์ จำกัด (มหาชน)', 'c71.jpg', 'ผู้ดำเนินธุรกิจค้าปลีกร้านสะดวกซื้อ (7-Eleven) และธุรกิจที่เกี่ยวข้องในเครือเจริญโภคภัณฑ์', 'กรุงเทพมหานคร', '313 อาคารซี.พี.ทาวเวอร์ ชั้นที่ 24 ถนนสีลม แขวงสีลม เขตบางรัก กรุงเทพมหานคร 10500'),
    (64, 'บริษัทบิ๊กซี ซูเปอร์เซ็นเตอร์ จํากัด (มหาชน)', 'c72.png', 'ผู้ประกอบธุรกิจค้าปลีก ไฮเปอร์มาร์เก็ต และซูเปอร์เซ็นเตอร์ชั้นนำของประเทศไทย', 'กรุงเทพมหานคร', '88/9 ซอยสมานฉันท์ - บาร์โบส แขวงพระโขนง เขตคลองเตย กรุงเทพมหานคร'),
    (65, 'บริษัท เมอร์ซิล โซลูชั่นส์ จำกัด', 'c73.png', 'บริษัทที่ปรึกษาและผู้ให้บริการพัฒนาระบบเทคโนโลยีสารสนเทศ (IT Consulting) ชั้นนำ', 'กรุงเทพมหานคร', '1371 อาคารแคปปิตอลแมนชั่น แขวงพญาไท เขตพญาไท กรุงเทพมหานคร 10400'),
    (66, 'บริษัท โกไฟว์ จำกัด', 'c74.png', 'สตาร์ทอัพผู้พัฒนาซอฟต์แวร์โซลูชันด้าน CRM และ ERP เพื่อช่วยบริหารจัดการและยกระดับธุรกิจ', 'สมุทรสาคร', '30/88 หมู่ที่ 1 ถนนเจษฎาวิถี ตำบลโคกขาม อำเภอเมืองสมุทรสาคร จ.สมุทรสาคร 74000'),
    (67, 'บริษัท แอสเซนด์ กรุ๊ป จำกัด', 'c75.jpeg', 'กลุ่มบริษัทเทคโนโลยีชั้นนำ ผู้ให้บริการด้าน FinTech (เช่น TrueMoney) และ E-commerce ในภูมิภาค', 'กรุงเทพมหานคร', '101 ทรู ดิจิทัล พาร์ค อาคารฟีนิกซ์ ชั้น 9-10 ถนนสุขุมวิท แขวงบางจาก เขตพระโขนง กรุงเทพมหานคร 10260'),
    (68, 'บริษัท บีทามส์ โซลูชั่น จำกัด', 'c76.png', 'ผู้ให้บริการออกแบบ พัฒนาซอฟต์แวร์ เว็บไซต์ และแอปพลิเคชันสำหรับลูกค้าองค์กร', 'กรุงเทพมหานคร', '84/4 ซอยสุขุมวิท 62 ถนนสุขุมวิท แขวงบางจาก เขตพระโขนง กรุงเทพมหานคร 10260'),
    (69, 'บริษัท ลูลู่ เทคโนโลยี จำกัด', 'c77.png', 'บริษัทผู้คิดค้นและพัฒนาโซลูชันเทคโนโลยี ดิจิทัลแพลตฟอร์ม และระบบซอฟต์แวร์สมัยใหม่', 'กรุงเทพมหานคร', '110/1 อาคารเคเอกซ์ ชั้นที่ 18 ถนนกรุงธนบุรี แขวงบางลำภูล่าง เขตคลองสาน กรุงเทพมหานคร 10600'),
    (70, 'บริษัท เฮาส์ออฟเดฟ เทคโนโลยี จำกัด', 'c78.jpeg', 'ผู้เชี่ยวชาญด้านการพัฒนาซอฟต์แวร์ โซลูชันไอที และแอปพลิเคชันตอบโจทย์ธุรกิจ', 'กรุงเทพมหานคร', '15 อาคารรัจนาการ ชั้น12บี ซอยประดิพัทธ์ 17 ถนนประดิพัทธ์ แขวงพญาไท เขตพญาไท กรุงเทพมหานคร 10400'),
    (71, 'บริษัท ยิบอินซอย จำกัด', 'c79.png', 'ผู้ให้บริการด้าน System Integration และโซลูชันเทคโนโลยีสารสนเทศแบบครบวงจรชั้นนำของประเทศ', 'กรุงเทพมหานคร', '523 ถนนมหาพฤฒาราม แขวงมหาพฤฒาราม เขตบางรัก กรุงเทพมหานคร 10500'),
    (72, 'บริษัท จัดหางาน จ๊อบบีเคเค ดอท คอม จำกัด', 'c80.jpeg', 'ผู้ให้บริการแพลตฟอร์มและเว็บไซต์จัดหางานชั้นนำของประเทศไทย (JOBBKK)', 'กรุงเทพมหานคร', '625 อาคารทัศนียา ห้องเลขที่ ยูนิตดี ชั้นที่ 5 ซอยรามคำแหง 39 ถนนประชาอุทิศ แขวงวังทองหลาง เขตวังทองหลาง กรุงเทพมหานคร 10310'),
    (73, 'บริษัท ล็อกซเล่ย์ จำกัด (มหาชน)', 'c81.jpeg', 'กลุ่มบริษัทชั้นนำผู้ให้บริการด้านเทคโนโลยี นวัตกรรมไอที และงานรับเหมาวางระบบโครงสร้างพื้นฐาน', 'กรุงเทพมหานคร', '102 ถนนณ ระนอง แขวงคลองเตย เขตคลองเตย กรุงเทพมหานคร 10110'),
    (74, 'บริษัท โมบาย คอนเน็ค จำกัด', 'c82.jpeg', 'ผู้ให้บริการโซลูชันด้านการสื่อสารโทรคมนาคม (SMS Solution) และดิจิทัลเซอร์วิสสำหรับองค์กร', 'กรุงเทพมหานคร', '1111/84 ถนนลาดพร้าว แขวงจันทรเกษม เขตจตุจักร กรุงเทพมหานคร 10900'),
    (75, 'อีวาย คาร์ปอเรท เซอร์วิสเซส', 'c83.png', 'เครือบริษัทที่ปรึกษาชั้นนำระดับโลก (EY) ให้บริการด้านการตรวจสอบบัญชี ภาษี และที่ปรึกษาธุรกิจ', 'กรุงเทพมหานคร', '193/136-137 อาคารเลครัชดา ชั้น 33 ถนนรัชดาภิเษก แขวงคลองเตย เขตคลองเตย กรุงเทพมหานคร 10110'),
    (76, 'บริษัท เอสซีจีซี ไอโค พอลิเมอร์ จำกัด', 'c84.png', 'ผู้ดำเนินธุรกิจ วิจัย และพัฒนาผลิตภัณฑ์พอลิเมอร์ชนิดพิเศษในเครือ SCGC', 'กรุงเทพมหานคร', '1 ถนนปูนซิเมนต์ไทย แขวงบางซื่อ เขตบางซื่อ กรุงเทพมหานคร 10800'),
    (77, 'บริษัท วีคาโบ้ จำกัด', 'c85.png', 'ผู้ให้บริการและพัฒนาเทคโนโลยีสารสนเทศ ซอฟต์แวร์ และดิจิทัลโซลูชัน', 'นนทบุรี', '11/1 ซอยประชาราษฎร์ 14 แยก 1 ตำบลตลาดขวัญ อำเภอเมืองนนทบุรี จ.นนทบุรี 11000'),
    (78, 'บริษัท ยูนิ ซีเคียวริตี้ จำกัด', 'c86.png', 'บริษัทผู้เชี่ยวชาญด้านการวางระบบและให้บริการโซลูชันด้านความมั่นคงปลอดภัยทางไซเบอร์ (Cybersecurity)', 'นนทบุรี', '198/426 หมู่ที่ 7ซอย 2 ตำบลมหาสวัสดิ์ อำเภอบางกรวย จ.นนทบุรี 11130'),
    (79, 'บริษัท แคนนอน ไฮ-เทค (ประเทศไทย) จำกัด', 'c87.png', 'ฐานการผลิต วิจัย และพัฒนาผลิตภัณฑ์เครื่องพิมพ์ (Printer) อุปกรณ์อิเล็กทรอนิกส์ของ Canon', 'พระนครศรีอยุธยา', '89 หมู่ที่ 1 ตำบลบ้านเลน อำเภอบางปะอิน จ.พระนครศรีอยุธยา 13160'),
    (80, 'บริษัท เวอร์นิตี้ จำกัด', 'c89.jpeg', 'ผู้ให้บริการโซลูชันระบบโครงสร้างพื้นฐานไอที ระบบเครือข่าย ศูนย์ข้อมูล และความปลอดภัยทางไซเบอร์', 'นนทบุรี', '111/151 หมู่ที่ 9 ตำบลบางพูด อำเภอปากเกร็ด จ.นนทบุรี 11120'),
    (81, 'บริษัท จิตตะ ดอท คอม จำกัด', 'c90.png', 'สตาร์ทอัพด้าน WealthTech ของไทย ผู้พัฒนาแพลตฟอร์มวิเคราะห์การลงทุนและเทคโนโลยีทางการเงิน (Jitta)', 'กรุงเทพมหานคร', '1111/127 ถนนลาดพร้าว แขวงจันทรเกษม เขตจตุจักร กรุงเทพมหานคร 10900'),
    (82, 'บริษัท เน็ตเบย์ จำกัด (มหาชน)', 'c91.png', 'ผู้ให้บริการพัฒนาระบบและแพลตฟอร์มการทำธุรกรรมทางอิเล็กทรอนิกส์ (e-Logistics และ e-Business)', 'กรุงเทพมหานคร', '719/5,8-9 ถนนพระรามที่ 6 แขวงวังใหม่ เขตปทุมวัน กรุงเทพมหานคร'),
    (83, 'บริษัท ที ลีสซิ่ง จำกัด', 'c92.png', 'ผู้ให้บริการธุรกิจสินเชื่อเช่าซื้อรถจักรยานยนต์ชั้นนำ ในเครือ MBK Group', 'กรุงเทพมหานคร', 'อาคารพาราไดซ์ เพลส ห้องเลขที่ 3801 ชั้น 3 เลขที่ 59/5 ถ.ศรีนครินทร์ แขวงหนองบอน เขตประเวศ กรุงเทพฯ 10250'),
    (84, 'ธนาคารกรุงศรีอยุธยา จำกัด (มหาชน)', 'c93.jpeg', 'สถาบันการเงินและธนาคารพาณิชย์ชั้นนำของประเทศ ให้บริการทางการเงินแก่ลูกค้ารายย่อยและองค์กร', 'กรุงเทพมหานคร', '1222 ถนนพระรามที่ 3 แขวงบางโพงพาง เขตยานนาวา กรุงเทพมหานคร 10120'),
    (85, 'บริษัท นิภา เทคโนโลยี จำกัด', 'c94.jpeg', 'ผู้ให้บริการโครงสร้างพื้นฐานคลาวด์ (Public Cloud) สัญชาติไทย และดิจิทัลเอเจนซีแบบครบวงจร', 'กรุงเทพมหานคร', 'บริษัท นิภา เทคโนโลยี จำกัด (สำนักงานใหญ่) 72 อาคารโทรคมนาคม บางรัก ชั้น 4 ห้อง 401-402 ถนนเจริญกรุง แขวงบางรัก เขตบางรัก กรุงเทพมหานคร 10500'),
    (86, 'บริษัท ดีไอทีซี จำกัด', 'c95.png', 'ผู้ให้บริการด้านไอที การพัฒนาเว็บไซต์ และระบบเครือข่ายสำหรับองค์กร ในเครือกลุ่มธรรมนิติ', 'กรุงเทพมหานคร', '178 อาคารธรรมนิติ ชั้น 4 ซอยเพิ่มทรัพย์ (ประชาชื่น20) ถนนประชาชื่น แขวงบางซื่อ เขตบางซื่อ กรุงเทพฯ 10800'),
    (87, 'บริษัท โตโยต้า มอเตอร์ ประเทศไทย จำกัด', 'c96.jpg', 'ผู้นำอุตสาหกรรมยานยนต์ ดำเนินธุรกิจผลิต ชิ้นส่วน และจัดจำหน่ายรถยนต์ชั้นนำของประเทศไทย', 'สมุทรปราการ', '186/1 หมู่ 1 ถ.ทางรถไฟเก่า ต.สำโรงใต้ อ.พระประแดง จ.สมุทรปราการ 10130'),
    (88, 'บริษัท ทรีนิตี้ รูทส์ จำกัด', 'c97.png', 'บริษัทผู้ให้บริการให้คำปรึกษา ออกแบบ และพัฒนาระบบซอฟต์แวร์ แพลตฟอร์มดิจิทัล', 'กรุงเทพมหานคร', '990 อาคารอับดุลราฮิม เพลส ห้องเลขที่ 2110 ชั้น 21 ถนนพระรามที่ 4 แขวงสีลม เขตบางรัก กรุงเทพมหานคร 10500'),
    (89, 'สถาบันวิจัยดาราศาสตร์แห่งชาติ (องค์การมหาชน)', 'c98.png', 'หน่วยงานของรัฐที่มีหน้าที่ศึกษาวิจัยและพัฒนาด้านดาราศาสตร์ วิทยาศาสตร์ และเทคโนโลยีอวกาศ (NARIT)', 'เชียงใหม่', '260 หมู่ 4 ต. ดอนแก้ว อ. แม่ริม จ. เชียงใหม่ 50180'),
    (90, 'บริษัท ไอ แอม คอนซัลติ้ง จำกัด', 'c99.png', 'บริษัทที่ปรึกษาด้านการจัดการองค์กรและพัฒนาระบบเทคโนโลยีสารสนเทศ (เช่น ERP Solutions)', 'กรุงเทพมหานคร', '252/69 อาคารเมืองไทย-ภัทร คอมเพล็กซ์ อาคารบี ชั้น 2 ถนนรัชดาภิเษก แขวงห้วยขวาง เขตห้วยขวาง กรุงเทพมหานคร 10310'),
    (91, 'บริษัท ทิพยประกันภัย จำกัด', 'c100.jpeg', 'บริษัทผู้นำด้านธุรกิจประกันวินาศภัยและให้บริการประกันภัยแบบครบวงจรชั้นนำของประเทศ', 'กรุงเทพมหานคร', '1115 ถนนพระราม 3 แขวงช่องนนทรี เขตยานนาวา กรุงเทพมหานคร 10120'),
    (92, 'ธนาคารกรุงไทย จำกัด', 'c101.jpeg', 'สถาบันการเงินและธนาคารพาณิชย์ของรัฐที่เป็นกลไกสำคัญในการขับเคลื่อนเศรษฐกิจของประเทศ', 'กรุงเทพมหานคร', '35 ถนนสุขุมวิท แขวงคลองตันเหนือ เขตวัฒนา กรุงเทพมหานคร 10110'),
    (93, 'บริษัท แวนเนส พลัส คอนซัลติ้ง จำกัด', 'c102.jpeg', 'ผู้ให้บริการที่ปรึกษาด้านเทคโนโลยีและพัฒนาระบบ CRM (เช่น Salesforce) เพื่อยกระดับธุรกิจ', 'กรุงเทพมหานคร', '98 อาคารสาทรสแควร์ ออฟฟิศ ทาวเวอร์ ชั้น 37 ถนนสาทรเหนือ แขวงสีลม เขตบางรัก กรุงเทพมหานคร 10500'),
    (94, 'บริษัท ไอแอพพ์เทคโนโลยี จำกัด', 'c103.png', 'สตาร์ทอัพด้านเทคโนโลยีผู้เชี่ยวชาญการวิจัย พัฒนา AI ปัญญาประดิษฐ์ด้านภาษาไทย และแชทบอท (iApp)', 'ปทุมธานี', '80/359 หมู่ที่ 3 ซ. คลองหลวง 26 ถ. พหลโยธิน ต.คลองหนึ่ง อ.คลองหลวง ปทุมธานี 12120 ประเทศไทย'),
    (95, 'บริษัท เอดไวซอรี่ เทค จำกัด', 'c104.png', 'บริษัทเทคโนโลยีผู้เชี่ยวชาญด้านการให้คำปรึกษาและพัฒนาระบบซอฟต์แวร์สำหรับองค์กร', 'กรุงเทพมหานคร', '111 ทรูดิจิทัล พาร์ค เวสต์ อาคารยูนิคอร์น ชั้น 5 ห้อง SH554 ถนนสุขุมวิท แขวงบางจาก เขตพระโขนง กรุงเทพมหานคร 10260'),
    (96, 'บริษัทหลักทรัพย์ อินโนเวสท์ เอกซ์ จำกัด', 'c105.webp', 'บริษัทหลักทรัพย์ในเครือ SCBX ผู้ให้บริการแพลตฟอร์มการลงทุนและเทคโนโลยีทางการเงินครบวงจร', 'กรุงเทพมหานคร', 'บริษัทหลักทรัพย์ อินโนเวสท์ เอกซ์ จำกัด ไทยพาณิชย์ ปาร์ค พลาซ่า เลขที่ 18 อาคาร 1 ชั้น 2, 4 ถนนรัชดาภิเษก แขวงจตุจักร เขตจตุจักร กรุงเทพมหานคร 10900'),
    (97, 'บริษัท เอสซีบี เดต้า เอกซ์ จำกัด', 'c106.png', 'บริษัทในกลุ่ม SCBX ที่ขับเคลื่อนธุรกิจด้วยการวิเคราะห์ข้อมูลขนาดใหญ่ (Data Analytics) และนวัตกรรม AI', 'กรุงเทพมหานคร', '18 อาคารไทยพาณิชย์ ปาร์ค พลาซ่า เวสท์ บี ชั้นที่ 7 ถนนรัชดาภิเษก แขวงจตุจักร เขตจตุจักร กรุงเทพมหานคร 10900'),
    (98, 'บริษัท เอวิชั่น จำกัด', 'c107.png', 'ผู้เชี่ยวชาญในการให้บริการโซลูชันระบบสแกนเอกสารและการบริหารจัดการข้อมูลอิเล็กทรอนิกส์ในองค์กร', 'กรุงเทพมหานคร', '979/49-50 อาคารเอส เอ็ม ทาวเวอร์ ชั้นที่ 20 ถนนพหลโยธิน แขวงพญาไท เขตพญาไท กรุงเทพมหานคร 10400'),
    (99, 'บริษัท สิริซอฟต์ จำกัด (มหาชน)', 'c108.jpeg', 'ผู้เชี่ยวชาญด้านให้คำปรึกษาไอที การออกแบบสถาปัตยกรรมคลาวด์ และพัฒนาซอฟต์แวร์แบบ DevOps', 'กรุงเทพมหานคร', '89 อาคารเอไอเอ แคปปิตอล เซ็นเตอร์ ชั้นที่ 15 ถนนรัชดาภิเษก แขวงดินแดง เขตดินแดง กรุงเทพมหานคร 10400'),
    (100, 'กองจัดการโลจิสติกส์ ภาคกลาง การไฟฟ้าส่วนภูมิภาค', 'c109.jpeg', 'หน่วยงานที่ดูแลระบบบริหารจัดการคลังพัสดุและเครือข่ายโลจิสติกส์ของการไฟฟ้าส่วนภูมิภาค (PEA)', 'ปทุมธานี', '60 หมู่ 6 ตำบลคลองหนึ่ง อำเภอคลองหลวง จังหวัดปทุมธานี 12120'),
    (101, 'บริษัท สยามมิชลิน จำกัด', 'c110.png', 'ผู้ผลิต จัดจำหน่าย และพัฒนานวัตกรรมยางรถยนต์แบรนด์ระดับโลก (Michelin) ประจำประเทศไทย', 'สมุทรปราการ', 'เลขที่ 32 หมู่ 2 ถนนปู่เจ้าสมิงพราย ตำบลสำโรงกลาง อำเภอพระประแดง จังหวัดสมุทรปราการ 10130'),
    (102, 'บริษัท แอสเซนด์ มันนี่ จำกัด', 'c111.jpeg', 'บริษัทฟินเทคชั้นนำ ผู้ให้บริการทางการเงินและแพลตฟอร์ม e-Wallet (TrueMoney) ระดับภูมิภาค', 'กรุงเทพมหานคร', 'อาคารทรู ดิจิทัล พาร์ค อาคารฟีนิกซ์ ชั้น 7-8 ถนนสุขุมวิท เขตพระโขนง กรุงเทพฯ 10260'),
    (103, 'บริษัท เซ็นทรัล เรสตอรองส์ กรุ๊ป จำกัด', 'c112.png', 'ผู้ดำเนินธุรกิจร้านอาหารและเครือข่ายแฟรนไชส์อาหารระดับแนวหน้าของไทย ในเครือเซ็นทรัล', 'กรุงเทพมหานคร', '306 เซ็นทรัลสีลมทาวเวอร์ ชั้น 5,6,7,8 ถนนสีลม แขวงสุริยวงศ์ เขตบางรัก กรุงเทพมหานคร 10500');
